from __future__ import annotations

import json

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class JudgmentSplitter(Component):
    display_name = "Judgment Splitter"
    description = (
        "Splits the relay-server input JSON {case_id, judgment, issue_catalog, scheme_catalog, catalog versions} "
        "into separate messages. Plain text input is treated as the judgment with empty catalogs."
    )
    icon = "Split"
    name = "JudgmentSplitter"

    inputs = [
        MessageTextInput(
            name="payload",
            display_name="Input JSON",
            info="JSON text from the relay server: {case_id, judgment, issue_catalog, issue_catalog_version, scheme_catalog, scheme_catalog_version}",
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="Judgment", name="judgment", method="build_judgment", group_outputs=True),
        Output(display_name="Issue Catalog", name="issue_catalog", method="build_issue_catalog", group_outputs=True),
        Output(display_name="Scheme Catalog", name="scheme_catalog", method="build_scheme_catalog", group_outputs=True),
        Output(display_name="Catalog Versions", name="catalog_versions", method="build_catalog_versions", group_outputs=True),
        Output(display_name="Case ID", name="case_id", method="build_case_id", group_outputs=True),
    ]

    def _payload(self) -> dict:
        raw = getattr(self.payload, "text", None)
        text = str(raw if raw is not None else (self.payload or ""))
        stripped = text.strip()
        if stripped.startswith("{"):
            try:
                # Langflow 가 tweak 값의 \n 이스케이프를 실제 줄바꿈으로 바꿔 전달하는 경우가 있어 문자열 안의 제어 문자를 허용한다.
                value = json.loads(stripped, strict=False)
            except ValueError:
                value = None
            if isinstance(value, dict) and isinstance(value.get("judgment"), str):
                return value
        return {"case_id": "", "judgment": text, "issue_catalog": [], "scheme_catalog": []}

    def build_judgment(self) -> Message:
        # 원문 문자·공백·줄바꿈을 그대로 전달한다 (근거 인용 매칭 정확도).
        return Message(text=self._payload().get("judgment") or "")

    def build_issue_catalog(self) -> Message:
        items = self._payload().get("issue_catalog") or []
        lines = []
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict) or not item.get("issueId"):
                continue
            lines.append(
                json.dumps(
                    {
                        "issue_id": str(item.get("issueId")),
                        "category": str(item.get("categoryName") or ""),
                        "label": str(item.get("label") or ""),
                        "criteria": str(item.get("criteria") or ""),
                    },
                    ensure_ascii=False,
                )
            )
        self.status = f"{len(lines)} catalog issues"
        return Message(text="\n".join(lines))

    def build_scheme_catalog(self) -> Message:
        items = self._payload().get("scheme_catalog") or []
        lines = [json.dumps(item, ensure_ascii=False) for item in items if isinstance(item, dict) and item.get("schemeKey")]
        return Message(text="\n".join(lines))

    def build_catalog_versions(self) -> Message:
        payload = self._payload()
        return Message(
            text=json.dumps(
                {"issue": payload.get("issue_catalog_version"), "scheme": payload.get("scheme_catalog_version")},
                ensure_ascii=False,
            )
        )

    def build_case_id(self) -> Message:
        return Message(text=str(self._payload().get("case_id") or ""))

from __future__ import annotations

import json
import re

import httpx
from lfx.custom import Component
from lfx.io import BoolInput, DropdownInput, FloatInput, IntInput, MessageTextInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
# 정답 그래프의 쟁점 수는 1~4개(평균 2.65)다. 여유를 두어 5개까지 받고, 몇 개를 고를지는 판결문이 정한다.
MAX_SELECTED = 5


class IssueSelector(Component):
    display_name = "Issue Selector"
    description = (
        "Reads the whole judgment and automatically selects the detailed issues the court actually decided (at most 5) from the 52-item "
        "issue catalog, each with a selection reason and a verbatim evidence quote. Validates the answer "
        "(at most 5, catalog IDs only, no duplicates, no two issues grounded in the same quote) with limited retries. Zero is allowed with a reason."
    )
    icon = "ListChecks"
    name = "IssueSelector"

    inputs = [
        MessageTextInput(name="judgment", display_name="Judgment", required=True),
        MessageTextInput(name="issue_catalog", display_name="Issue Catalog (JSON lines)", required=True),
        MessageTextInput(name="claim_json", display_name="Main Claim JSON", required=True),
        MultilineInput(
            name="prompt_template",
            display_name="Selection Prompt Template",
            info="Variables: {max_issues}, {main_claim}, {issue_catalog}, {judgment}. Substituted literally.",
            value="",
        ),
        MultilineInput(name="system_message", display_name="System Message", value="", advanced=True),
        StrInput(name="base_url", display_name="Ollama Base URL", value="http://localhost:11434"),
        DropdownInput(
            name="model_name",
            display_name="Model Name",
            options=["qwen36-27b-q8-ctx32k", "qwen36-27b-q8-ctx32k-np", "gemma4-e4b-ctx32k", "gemma4:e4b-it-qat", "qwen2.5:14b-instruct"],
            value="qwen36-27b-q8-ctx32k",
            combobox=True,
        ),
        BoolInput(
            name="think",
            display_name="Thinking",
            value=False,
            info="추론 모델의 사고 과정을 켠다. 답의 JSON 은 그대로지만 생성이 10배 이상 느려진다.",
            advanced=True,
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="num_ctx", display_name="Context Window Size", value=32768),
        IntInput(name="timeout", display_name="Timeout per call (s)", value=600, info="0 = no limit"),
        IntInput(name="retries", display_name="Retries on invalid answer", value=2, advanced=True),
    ]

    outputs = [Output(display_name="Selection JSON", name="selection_json", method="select")]

    # ---- helpers ----
    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def parse_json_object(text: str) -> dict:
        stripped = str(text or "").strip()
        match = _FENCE.match(stripped)
        if match:
            stripped = match.group(1).strip()
        value = json.loads(stripped, strict=False)
        if not isinstance(value, dict):
            raise ValueError("answer must be a JSON object")
        return value

    @staticmethod
    def catalog_ids(text: str) -> list[str]:
        ids = []
        for line in str(text or "").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line, strict=False)
            except ValueError:
                continue
            if isinstance(item, dict) and item.get("issue_id"):
                ids.append(str(item["issue_id"]))
        return ids

    @staticmethod
    def validate_selection(obj: dict, catalog: set[str]) -> tuple[list[dict], str, list[str]]:
        """(선택 목록, 0개 사유, 오류). 오류가 있으면 재시도 대상."""
        errors: list[str] = []
        items = obj.get("selected_issues")
        if not isinstance(items, list):
            return [], "", ["selected_issues must be an array"]
        if len(items) > MAX_SELECTED:
            errors.append(f"selected {len(items)} issues; at most {MAX_SELECTED} are allowed")
        selected: list[dict] = []
        seen: set[str] = set()
        quotes_seen: dict[str, int] = {}
        for index, item in enumerate(items, start=1):
            if not isinstance(item, dict):
                errors.append(f"selected_issues[{index}] must be an object")
                continue
            issue_id = str(item.get("issue_id") or "").strip()
            if issue_id not in catalog:
                errors.append(f"selected_issues[{index}].issue_id {issue_id!r} is not in the issue catalog")
                continue
            if issue_id in seen:
                errors.append(f"issue_id {issue_id} is selected more than once")
                continue
            seen.add(issue_id)
            issue_text = str(item.get("issue_text") or "").strip()
            reason = str(item.get("selection_reason") or "").strip()
            if not issue_text:
                errors.append(f"selected_issues[{index}].issue_text is empty")
            if not reason:
                errors.append(f"selected_issues[{index}].selection_reason is empty")
            quote = str(item.get("evidence_quote") or "").strip()
            # 같은 대목을 근거로 든 두 쟁점은 한 쟁점을 쪼갠 것이다. 수를 채우려고 나눈 경우를 막는다.
            if quote and quote in quotes_seen:
                errors.append(
                    f"selected_issues[{index}] is grounded in the same quote as selected_issues[{quotes_seen[quote]}]; "
                    "select one issue for one ground instead of splitting it"
                )
                continue
            if quote:
                quotes_seen[quote] = index
            selected.append(
                {
                    "issue_id": issue_id,
                    "issue_text": issue_text,
                    "selection_reason": reason,
                    "evidence_quote": str(item.get("evidence_quote") or "").strip(),
                }
            )
        no_issue_reason = str(obj.get("no_issue_reason") or "").strip()
        if not items and not no_issue_reason:
            errors.append("no issue selected but no_issue_reason is empty")
        return selected, no_issue_reason, errors

    def render_prompt(self, template: str, main_claim: str, catalog: str, judgment: str) -> str:
        rendered = template.replace("{max_issues}", str(MAX_SELECTED)).replace("{main_claim}", main_claim)
        rendered = rendered.replace("{issue_catalog}", catalog)
        # 판결문은 마지막에 넣어 원문 안의 중괄호가 변수로 오인되지 않게 한다.
        return rendered.replace("{judgment}", judgment)

    def call_model(self, messages: list[dict]) -> dict:
        payload = {
            "model": self._text(self.model_name),
            "messages": messages,
            "format": "json",
            "stream": False,
            "think": bool(getattr(self, "think", False)),
            "options": {"temperature": float(self.temperature or 0), "num_ctx": int(self.num_ctx or 2048)},
        }
        timeout = int(self.timeout or 0)
        response = httpx.post(
            f"{self._text(self.base_url).rstrip('/')}/api/chat",
            json=payload,
            timeout=None if timeout <= 0 else float(timeout),
        )
        if response.status_code >= 400:
            raise RuntimeError(f"Ollama HTTP {response.status_code}: {response.text[:300]}")
        body = response.json()
        return {
            "content": (body.get("message") or {}).get("content") or "",
            "prompt_eval_count": body.get("prompt_eval_count"),
            "done_reason": body.get("done_reason"),
        }

    def select(self) -> Message:
        catalog_text = self._text(self.issue_catalog)
        catalog = set(self.catalog_ids(catalog_text))
        if not catalog:
            raise ValueError("Issue catalog is empty; the relay server must send the 52-item catalog.")
        template = self._text(self.prompt_template)
        if not template.strip():
            raise ValueError("Selection Prompt Template is empty.")
        try:
            main_claim = str(self.parse_json_object(self._text(self.claim_json)).get("main_claim") or "").strip()
        except ValueError:
            main_claim = ""
        prompt = self.render_prompt(template, main_claim, catalog_text, self._text(self.judgment))
        messages = []
        system = self._text(getattr(self, "system_message", ""))
        if system.strip():
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})

        attempts = max(1, int(self.retries or 0) + 1)
        errors: list[str] = []
        warnings: list[str] = []
        for attempt in range(1, attempts + 1):
            try:
                result = self.call_model(messages)
            except Exception as error:  # noqa: BLE001 - 호출 오류도 기록하고 재시도한다.
                errors = [f"attempt {attempt}: {error.__class__.__name__}: {error}"]
                continue
            content = result.get("content", "")
            used = result.get("prompt_eval_count")
            num_ctx = int(self.num_ctx or 0)
            if isinstance(used, int) and num_ctx and used >= num_ctx - 8:
                warnings.append(f"context_limit: prompt used {used} of {num_ctx} tokens; the judgment may have been truncated.")
            try:
                obj = self.parse_json_object(content)
            except ValueError as error:
                errors = [f"attempt {attempt}: invalid JSON: {error}"]
            else:
                selected, reason, errors = self.validate_selection(obj, catalog)
                if not errors:
                    status = "ok" if selected else "no_issues"
                    self.status = f"{status}: {', '.join(i['issue_id'] for i in selected) or reason}"
                    return Message(
                        text=json.dumps(
                            {
                                "status": status,
                                "selected": selected,
                                "no_issue_reason": reason,
                                "attempts": attempt,
                                "warnings": sorted(set(warnings)),
                                "model": self._text(self.model_name),
                            },
                            ensure_ascii=False,
                        )
                    )
            # 제한된 재시도: 무엇이 틀렸는지 알려 주고 다시 답하게 한다.
            messages = [
                *messages,
                {"role": "assistant", "content": content},
                {
                    "role": "user",
                    "content": "Your previous answer was invalid:\n- "
                    + "\n- ".join(errors)
                    + f"\nReturn corrected JSON only. Select at most {MAX_SELECTED} distinct issue_id values from the catalog, "
                    + "one per separate ground the court decided. Do not add issues to reach the maximum.",
                },
            ]
        self.status = "invalid selection"
        return Message(
            text=json.dumps(
                {"status": "invalid", "selected": [], "no_issue_reason": "", "attempts": attempts, "errors": errors, "warnings": sorted(set(warnings))},
                ensure_ascii=False,
            )
        )

from __future__ import annotations

import json
import re
import time

import httpx
from lfx.custom import Component
from lfx.io import BoolInput, DropdownInput, FloatInput, IntInput, MessageTextInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
# 정답 그래프의 쟁점 수는 1~4개(평균 2.65)다. 여유를 두어 5개까지 받고, 몇 개를 고를지는 판결문이 정한다.
MAX_SELECTED = 5


class BranchError(ValueError):
    pass


class IssueBranchExtractor(Component):
    display_name = "Issue Branch Extractor"
    description = (
        "For each selected issue (at most 5) calls Ollama once to extract the upper/lower I-node texts with "
        "verbatim evidence quotes. Summaries and Walton schemes are produced by later stages. Per-issue failures "
        "and context-limit warnings are reported instead of being dropped."
    )
    icon = "GitBranch"
    name = "IssueBranchExtractor"

    inputs = [
        MessageTextInput(name="selection_json", display_name="Selection JSON", required=True),
        MessageTextInput(name="judgment", display_name="Judgment", required=True),
        MessageTextInput(name="claim_json", display_name="Main Claim JSON", required=True),
        MultilineInput(
            name="prompt_template",
            display_name="Branch Prompt Template",
            info="Variables: {issue_json}, {main_claim}, {judgment}. Substituted literally (JSON braces are safe).",
            value="",
        ),
        MultilineInput(name="system_message", display_name="System Message", value="", advanced=True),
        StrInput(name="base_url", display_name="Ollama Base URL", value="http://localhost:11434"),
        DropdownInput(
            name="model_name",
            display_name="Model Name",
            options=["qwen36-27b-q8-ctx32k", "qwen36-27b-q8-ctx32k-np", "gemma4-e4b-ctx32k", "gemma4:e4b-it-qat", "qwen2.5:14b-instruct"],
            value="qwen36-27b-q8-ctx32k",
            combobox=True,
        ),
        BoolInput(
            name="think",
            display_name="Thinking",
            value=False,
            info="추론 모델의 사고 과정을 켠다. 답의 JSON 은 그대로지만 생성이 10배 이상 느려진다.",
            advanced=True,
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="num_ctx", display_name="Context Window Size", value=32768),
        IntInput(name="timeout", display_name="Timeout per issue (s)", value=600, info="0 = no limit"),
        IntInput(name="retries", display_name="Retries on invalid JSON", value=1, advanced=True),
    ]

    outputs = [Output(display_name="Branches JSON", name="branches_json", method="extract")]

    # ---- parsing helpers (pure) ----
    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def parse_json_object(text: str, label: str) -> dict:
        stripped = str(text or "").strip()
        match = _FENCE.match(stripped)
        if match:
            stripped = match.group(1).strip()
        try:
            value = json.loads(stripped, strict=False)
        except ValueError as error:
            raise BranchError(f"{label} is not valid JSON: {error}") from error
        if not isinstance(value, dict):
            raise BranchError(f"{label} must be a JSON object.")
        return value

    @staticmethod
    def validate_branch(obj: dict) -> dict:
        upper = obj.get("upper_i_node")
        if isinstance(upper, str):
            upper = {"text": upper}
        if not isinstance(upper, dict) or not str(upper.get("text") or "").strip():
            raise BranchError("upper_i_node.text is missing.")
        lowers = obj.get("lower_i_nodes")
        if not isinstance(lowers, list) or not lowers:
            raise BranchError("lower_i_nodes must be a non-empty array.")
        normalized = []
        for index, lower in enumerate(lowers, start=1):
            if isinstance(lower, str):
                lower = {"text": lower}
            if not isinstance(lower, dict) or not str(lower.get("text") or "").strip():
                raise BranchError(f"lower_i_nodes[{index}].text is missing.")
            normalized.append({"text": str(lower["text"]).strip(), "evidence_quote": str(lower.get("evidence_quote") or "").strip()})
        return {
            "upper_i_node": {"text": str(upper["text"]).strip(), "evidence_quote": str(upper.get("evidence_quote") or "").strip()},
            "lower_i_nodes": normalized,
        }

    @staticmethod
    def render_prompt(template: str, issue: dict, main_claim: str, judgment: str) -> str:
        rendered = template.replace("{issue_json}", json.dumps(issue, ensure_ascii=False, indent=2))
        rendered = rendered.replace("{main_claim}", main_claim)
        # 판결문을 마지막에 넣어 원문 안의 중괄호가 다른 변수로 오인되지 않게 한다.
        return rendered.replace("{judgment}", judgment)

    # ---- model call ----
    def call_model(self, prompt: str) -> dict:
        messages = []
        system = self._text(getattr(self, "system_message", ""))
        if system.strip():
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})
        payload = {
            "model": self._text(self.model_name),
            "messages": messages,
            "format": "json",
            "stream": False,
            "think": bool(getattr(self, "think", False)),
            "options": {"temperature": float(self.temperature or 0), "num_ctx": int(self.num_ctx or 2048)},
        }
        timeout = int(self.timeout or 0)
        response = httpx.post(
            f"{self._text(self.base_url).rstrip('/')}/api/chat",
            json=payload,
            timeout=None if timeout <= 0 else float(timeout),
        )
        if response.status_code >= 400:
            raise BranchError(f"Ollama HTTP {response.status_code}: {response.text[:300]}")
        body = response.json()
        return {
            "content": (body.get("message") or {}).get("content") or "",
            "prompt_eval_count": body.get("prompt_eval_count"),
            "done_reason": body.get("done_reason"),
        }

    def extract_one(self, index: int, issue: dict, main_claim: str, judgment: str, template: str) -> dict:
        prompt = self.render_prompt(
            template,
            {"issue_id": issue["issue_id"], "issue_text": issue["issue_text"], "selection_reason": issue["selection_reason"]},
            main_claim,
            judgment,
        )
        attempts = max(1, int(self.retries or 0) + 1)
        warnings: list[str] = []
        last_error = ""
        started = time.monotonic()
        for attempt in range(1, attempts + 1):
            try:
                result = self.call_model(prompt)
            except Exception as error:  # noqa: BLE001 - 쟁점별 오류로 기록한다.
                last_error = f"{error.__class__.__name__}: {error}"
                continue
            num_ctx = int(self.num_ctx or 0)
            used = result.get("prompt_eval_count")
            if isinstance(used, int) and num_ctx and used >= num_ctx - 8:
                warnings.append(f"context_limit: prompt used {used} of {num_ctx} tokens; the judgment may have been truncated.")
            if result.get("done_reason") == "length":
                warnings.append("output_truncated: the model stopped at the length limit.")
            try:
                branch = self.validate_branch(self.parse_json_object(result["content"], "branch output"))
            except BranchError as error:
                last_error = f"attempt {attempt}: {error}"
                continue
            return {
                "issue_id": issue["issue_id"],
                "issue_index": index,
                "status": "ok",
                "attempts": attempt,
                "seconds": round(time.monotonic() - started, 1),
                "warnings": sorted(set(warnings)),
                **branch,
            }
        return {
            "issue_id": issue["issue_id"],
            "issue_index": index,
            "status": "failed",
            "attempts": attempts,
            "seconds": round(time.monotonic() - started, 1),
            "error": last_error or "unknown error",
            "warnings": sorted(set(warnings)),
        }

    def extract(self) -> Message:
        selection = self.parse_json_object(self._text(self.selection_json), "Selection JSON")
        status = selection.get("status")
        selected = selection.get("selected") if isinstance(selection.get("selected"), list) else []
        if status != "ok":
            # 쟁점이 없거나 선택이 무효면 가지를 만들지 않는다(가짜 추출 금지).
            self.status = f"skipped: selection status {status}"
            return Message(text=json.dumps({"status": "skipped", "reason": f"selection status {status}", "branches": []}, ensure_ascii=False))
        if len(selected) > MAX_SELECTED:
            raise ValueError(f"Selection has {len(selected)} issues; at most {MAX_SELECTED} are allowed.")
        try:
            main_claim = str(self.parse_json_object(self._text(self.claim_json), "Main Claim JSON").get("main_claim") or "").strip()
        except BranchError:
            main_claim = ""
        template = self._text(self.prompt_template)
        if not template.strip():
            raise ValueError("Branch Prompt Template is empty.")
        judgment = self._text(self.judgment)
        branches = [self.extract_one(index, issue, main_claim, judgment, template) for index, issue in enumerate(selected, start=1)]
        summary = {
            "selected": len(selected),
            "ok": sum(1 for b in branches if b["status"] == "ok"),
            "failed": sum(1 for b in branches if b["status"] == "failed"),
        }
        self.status = f"{summary['ok']} ok / {summary['failed']} failed"
        return Message(text=json.dumps({"status": "done", "summary": summary, "branches": branches}, ensure_ascii=False))

from __future__ import annotations

import json
import re

import httpx
from lfx.custom import Component
from lfx.io import BoolInput, DropdownInput, FloatInput, IntInput, MessageTextInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
# 모델 입력용 별칭(R1, N2…)이 한국어 설명에 섞인 경우: 괄호 묶음은 지우고, 맨 별칭은 "해당 전제/추론"으로 바꾼다.
# 그 그룹에 실제로 준 별칭만 지운다 (판결문의 "N95" 같은 표기는 건드리지 않는다).
_ALIAS = r"[RN]\d{1,2}"
_ALIAS_LIST = rf"(?<![A-Za-z0-9]){_ALIAS}(?:\s*(?:,|/|·|와|과|및)\s*{_ALIAS})*(?![A-Za-z0-9])"
_ALIAS_PAREN = re.compile(rf"\s*[(\[（]\s*({_ALIAS_LIST})\s*[)\]）]")
_ALIAS_AFTER_WORD = re.compile(rf"(전제|추론|노드)\s*({_ALIAS_LIST})")
_ALIAS_BARE = re.compile(rf"({_ALIAS_LIST})")
_ALIAS_TOKEN = re.compile(_ALIAS)
RESERVED = ("unclassified", "custom")
CQ_STATUSES = ("open", "satisfied", "challenged")
# 쟁점 노드에 닿는 RA 는 실질 추론이 아니라 그래프의 구조 관계다. 모델에게 묻지 않고 구조로 정한다.
# (묻게 두면 아래 추론을 다시 서술하거나 미분류로 떨어진다.)
ISSUE_RESOLUTION = "issue_resolution"
ISSUE_AGGREGATION = "issue_aggregation"
STRUCTURAL_ROLES = {ISSUE_RESOLUTION: "finding", ISSUE_AGGREGATION: "issueFinding"}
STRUCTURAL_RATIONALES = {
    ISSUE_RESOLUTION: "쟁점을 결론으로 두는 연결이므로 쟁점 판단 관계로 둔다. 실질 추론은 이 아래 RA 가 담는다.",
    ISSUE_AGGREGATION: "쟁점별 판단을 종국 판단으로 잇는 연결이므로 쟁점 종합 관계로 둔다.",
}


class SchemeAssigner(Component):
    display_name = "RA Scheme Assigner"
    description = (
        "RA scheme assignment stage. RAs that touch an ISSUE node are graph structure, not substantive inference, so "
        "they are assigned from the structure ('issue_resolution' when the ISSUE is the conclusion, 'issue_aggregation' "
        "when ISSUEs are the premises) and are never sent to the model. Every other RA is classified with one scheme "
        "key from the allowed Walton scheme catalog (or 'unclassified' when none fits), based on the full premise "
        "texts, the conclusion text and their evidence quotes - not on summaries. Validates keys, roles and premise "
        "references with a limited retry; invalid parts are recorded as errors and never invented."
    )
    icon = "Workflow"
    name = "SchemeAssigner"

    inputs = [
        MessageTextInput(name="graph_json", display_name="Graph JSON", required=True),
        MessageTextInput(name="scheme_catalog", display_name="Scheme Catalog (JSON lines)", required=True),
        MultilineInput(
            name="prompt_template",
            display_name="Scheme Prompt Template",
            info="Variables: {scheme_catalog}, {ra_items_json}. Substituted literally.",
            value="",
        ),
        MultilineInput(name="system_message", display_name="System Message", value="", advanced=True),
        StrInput(name="base_url", display_name="Ollama Base URL", value="http://localhost:11434"),
        DropdownInput(
            name="model_name",
            display_name="Model Name",
            options=["qwen36-27b-q8-ctx32k", "qwen36-27b-q8-ctx32k-np", "gemma4-e4b-ctx32k", "gemma4:e4b-it-qat", "qwen2.5:14b-instruct"],
            value="qwen36-27b-q8-ctx32k",
            combobox=True,
        ),
        BoolInput(
            name="think",
            display_name="Thinking",
            value=False,
            info="추론 모델의 사고 과정을 켠다. 답의 JSON 은 그대로지만 생성이 10배 이상 느려진다.",
            advanced=True,
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="num_ctx", display_name="Context Window Size", value=32768),
        IntInput(name="timeout", display_name="Timeout per call (s)", value=600, info="0 = no limit"),
        IntInput(name="retries", display_name="Retries on invalid answer", value=1, advanced=True),
    ]

    outputs = [Output(display_name="Classified Graph JSON", name="classified_graph", method="assign")]

    # ---- helpers ----
    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def parse_json_object(text: str) -> dict:
        stripped = str(text or "").strip()
        match = _FENCE.match(stripped)
        if match:
            stripped = match.group(1).strip()
        value = json.loads(stripped, strict=False)
        if not isinstance(value, dict):
            raise ValueError("answer must be a JSON object")
        return value

    @staticmethod
    def read_catalog(text: str) -> dict[str, dict]:
        catalog = {}
        for line in str(text or "").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line, strict=False)
            except ValueError:
                continue
            if isinstance(item, dict) and item.get("schemeKey"):
                catalog[item["schemeKey"]] = item
        return catalog

    @staticmethod
    def selectable_catalog_text(text: str) -> str:
        """모델에게 보여줄 카탈로그. 구조로 정해지는 쟁점 관계 scheme 은 고르지 못하도록 뺀다."""
        kept = []
        for line in str(text or "").splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            try:
                item = json.loads(stripped, strict=False)
            except ValueError:
                kept.append(line)
                continue
            if isinstance(item, dict) and item.get("schemeKey") in STRUCTURAL_ROLES:
                continue
            kept.append(line)
        return "\n".join(kept)

    @staticmethod
    def groups(graph: dict) -> list[dict]:
        """쟁점 가지(instance)별로 RA 와 전제·결론 노드를 묶는다."""
        nodes = {n["nodeID"]: n for n in graph["AIF"]["nodes"]}
        incoming: dict[str, list[str]] = {}
        outgoing: dict[str, list[str]] = {}
        for edge in graph["AIF"]["edges"]:
            incoming.setdefault(edge["toID"], []).append(edge["fromID"])
            outgoing.setdefault(edge["fromID"], []).append(edge["toID"])
        grouped: dict[str, list[dict]] = {}
        for node in graph["AIF"]["nodes"]:
            if node.get("type") != "RA":
                continue
            refs = node.get("issueRefs") or []
            key = refs[0]["instanceId"] if refs and isinstance(refs[0], dict) and refs[0].get("instanceId") else "main"
            grouped.setdefault(key, []).append(
                {
                    "ra": node,
                    "premises": [nodes[i] for i in incoming.get(node["nodeID"], []) if i in nodes],
                    "conclusions": [nodes[i] for i in outgoing.get(node["nodeID"], []) if i in nodes],
                }
            )
        return [{"instanceId": key, "items": items} for key, items in grouped.items()]

    @staticmethod
    def structural_key(entry: dict) -> str | None:
        """쟁점 노드에 닿는 RA 인지 구조로 판별한다. 아니면 None (모델이 분류한다)."""
        if any(node.get("type") == "ISSUE" for node in entry["conclusions"]):
            return ISSUE_RESOLUTION
        if any(node.get("type") == "ISSUE" for node in entry["premises"]):
            return ISSUE_AGGREGATION
        return None

    @staticmethod
    def structural_application(entry: dict, key: str, catalog: dict[str, dict]) -> tuple[dict, list[str]]:
        """구조로 정해지는 RA 의 schemeApplication. 모델을 부르지 않으므로 지어낸 설명이 들어가지 않는다."""
        errors: list[str] = []
        if key not in catalog:
            errors.append(f"scheme_key {key!r} is not in the catalog; the catalog must define the issue relation schemes")
            key = "unclassified"
        role = STRUCTURAL_ROLES.get(key)
        node_ids = [p["nodeID"] for p in entry["premises"]]
        return (
            {
                "schemeKey": key,
                "status": "suggested",
                "origin": "ai",
                "rationale": STRUCTURAL_RATIONALES.get(key, ""),
                "premiseBindings": [{"roleId": role, "nodeIds": node_ids}] if role and node_ids else [],
                "conclusionNodeIds": [c["nodeID"] for c in entry["conclusions"]],
                # 비판적 질문은 사람이 검토할 몫이라 열어 둔다.
                "criticalQuestionResponses": [
                    {"questionId": q["id"], "status": "open", "answer": ""} for q in catalog.get(key, {}).get("criticalQuestions", [])
                ],
                "notes": "",
                "customSchemeName": None,
                "alternatives": [],
            },
            errors,
        )

    @staticmethod
    def strip_aliases(text, known: set[str]) -> str:
        """설명 문장에서 모델 입력용 별칭(known)을 없앤다. 사용자 화면에는 별칭이 없어 뜻이 통하지 않는다."""

        def only_known(group: str) -> bool:
            return all(token in known for token in _ALIAS_TOKEN.findall(group))

        def bare(match: re.Match) -> str:
            if not only_known(match.group(1)):
                return match.group(0)
            return "해당 추론" if match.group(1).startswith("R") else "해당 전제"

        text = str(text or "")
        text = _ALIAS_PAREN.sub(lambda m: "" if only_known(m.group(1)) else m.group(0), text)
        text = _ALIAS_AFTER_WORD.sub(lambda m: m.group(1) if only_known(m.group(2)) else m.group(0), text)
        text = _ALIAS_BARE.sub(bare, text)
        return re.sub(r"[ \t]{2,}", " ", text).strip()

    @staticmethod
    def quotes(node: dict) -> list[str]:
        return [e.get("quote") for e in node.get("evidence") or [] if isinstance(e, dict) and e.get("quote")]

    def build_items(self, group: dict) -> tuple[list[dict], dict[str, dict]]:
        """LLM 에는 짧은 별칭(R1, N1…)으로 준다. 반환: (프롬프트 항목, 별칭 → 실제 ID 정보)."""
        items: list[dict] = []
        aliases: dict[str, dict] = {}
        node_counter = 0
        for index, entry in enumerate(group["items"], start=1):
            ra_alias = f"R{index}"
            premise_aliases = {}
            premises = []
            for premise in entry["premises"]:
                node_counter += 1
                alias = f"N{node_counter}"
                premise_aliases[alias] = premise["nodeID"]
                premises.append({"id": alias, "type": premise["type"], "text": premise["text"], "evidence_quotes": self.quotes(premise)})
            conclusions = [{"type": c["type"], "text": c["text"], "evidence_quotes": self.quotes(c)} for c in entry["conclusions"]]
            aliases[ra_alias] = {"ra": entry["ra"], "premises": premise_aliases, "conclusions": [c["nodeID"] for c in entry["conclusions"]]}
            items.append({"ra": ra_alias, "premises": premises, "conclusion": conclusions[0] if len(conclusions) == 1 else conclusions})
        return items, aliases

    @staticmethod
    def validate_assignment(raw: dict, alias: dict, catalog: dict[str, dict], known_aliases: set[str] | None = None) -> tuple[dict, list[str]]:
        """한 RA 의 답을 schemeApplication 필드로 바꾼다. (결과, 오류)"""
        errors: list[str] = []
        known = known_aliases if known_aliases is not None else set(alias["premises"])
        key = str(raw.get("scheme_key") or "").strip()
        if key in STRUCTURAL_ROLES:
            # 쟁점 관계 scheme 은 구조로만 정한다. 모델이 고르면 받지 않는다.
            errors.append(f"scheme_key {key!r} is assigned by graph structure only and cannot be chosen")
            key = "unclassified"
        elif key not in catalog and key not in RESERVED:
            errors.append(f"scheme_key {key!r} is not allowed")
            key = "unclassified"
        roles = {r["roleId"] for r in catalog[key]["premiseRoles"]} if key in catalog else set()
        questions = {q["id"] for q in catalog[key]["criticalQuestions"]} if key in catalog else set()
        bindings = []
        bound_refs: dict[str, str] = {}
        for binding in raw.get("premise_bindings") or []:
            if not isinstance(binding, dict):
                continue
            role = str(binding.get("role_id") or "").strip()
            if key in catalog and role not in roles:
                errors.append(f"role_id {role!r} is not a role of {key}")
                continue
            node_ids = []
            for ref in binding.get("premises") or []:
                ref = str(ref)
                real = alias["premises"].get(ref)
                if real is None:
                    errors.append(f"premise reference {ref!r} is not a premise of this RA")
                elif ref in bound_refs and bound_refs[ref] != role:
                    # 한 명제가 서로 다른 두 전제 역할을 동시에 채울 수는 없다. 처음 역할만 남긴다.
                    errors.append(f"premise {ref} is bound to more than one role ({bound_refs[ref]}, {role}); bind each premise to at most one role")
                elif ref not in bound_refs:
                    bound_refs[ref] = role
                    node_ids.append(real)
            if node_ids:
                bindings.append({"roleId": role or None, "nodeIds": node_ids})
        responses = []
        for item in raw.get("critical_question_responses") or []:
            if not isinstance(item, dict):
                continue
            question_id = str(item.get("question_id") or "").strip()
            if question_id not in questions:
                errors.append(f"question_id {question_id!r} is not defined for {key}")
                continue
            status = str(item.get("status") or "").strip().lower()
            responses.append(
                {
                    "questionId": question_id,
                    "status": status if status in CQ_STATUSES else "open",
                    "answer": SchemeAssigner.strip_aliases(item.get("answer"), known),
                }
            )
        alternatives = []
        for item in raw.get("alternatives") or []:
            if not isinstance(item, dict):
                continue
            alt = str(item.get("scheme_key") or "").strip()
            if alt in catalog and alt != key:
                alternatives.append({"schemeKey": alt, "rationale": SchemeAssigner.strip_aliases(item.get("rationale"), known)})
            elif alt:
                errors.append(f"alternative scheme_key {alt!r} is not allowed")
        custom_name = str(raw.get("custom_scheme_name") or "").strip() or None
        return (
            {
                "schemeKey": key,
                "status": "suggested",
                "origin": "ai",
                "rationale": SchemeAssigner.strip_aliases(raw.get("rationale"), known),
                "premiseBindings": bindings,
                "conclusionNodeIds": alias["conclusions"],
                "criticalQuestionResponses": responses,
                "notes": "",
                "customSchemeName": custom_name if key == "custom" else None,
                "alternatives": alternatives,
            },
            errors,
        )

    def call_model(self, messages: list[dict]) -> str:
        timeout = int(self.timeout or 0)
        response = httpx.post(
            f"{self._text(self.base_url).rstrip('/')}/api/chat",
            json={
                "model": self._text(self.model_name),
                "messages": messages,
                "format": "json",
                "stream": False,
                "think": bool(getattr(self, "think", False)),
                "options": {"temperature": float(self.temperature or 0), "num_ctx": int(self.num_ctx or 2048)},
            },
            timeout=None if timeout <= 0 else float(timeout),
        )
        if response.status_code >= 400:
            raise RuntimeError(f"Ollama HTTP {response.status_code}: {response.text[:300]}")
        return (response.json().get("message") or {}).get("content") or ""

    def assign_group(self, group: dict, catalog: dict[str, dict], catalog_text: str, template: str, version) -> list[str]:
        # 쟁점에 닿는 RA 는 구조로 정하고 모델에게 보내지 않는다.
        structural = [(entry, key) for entry in group["items"] if (key := self.structural_key(entry))]
        remaining = {"instanceId": group["instanceId"], "items": [entry for entry in group["items"] if not self.structural_key(entry)]}
        report: list[str] = []
        for entry, key in structural:
            application, errors = self.structural_application(entry, key, catalog)
            application["catalogVersion"] = version
            if errors:
                application["errors"] = errors
                report.append(f"{entry['ra']['nodeID']}: " + "; ".join(errors))
            entry["ra"]["schemeApplication"] = application
        if not remaining["items"]:
            return report

        items, aliases = self.build_items(remaining)
        selectable = self.selectable_catalog_text(catalog_text)
        prompt = template.replace("{scheme_catalog}", selectable).replace("{ra_items_json}", json.dumps(items, ensure_ascii=False, indent=2))
        messages = []
        system = self._text(getattr(self, "system_message", ""))
        if system.strip():
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})
        results: dict[str, tuple[dict, list[str]]] = {}
        group_errors: list[str] = []
        known_aliases = set(aliases) | {ref for info in aliases.values() for ref in info["premises"]}
        for attempt in range(1, max(1, int(self.retries or 0) + 1) + 1):
            try:
                content = self.call_model(messages)
                answer = self.parse_json_object(content)
            except Exception as error:  # noqa: BLE001
                group_errors = [f"attempt {attempt}: {error.__class__.__name__}: {error}"]
                continue
            feedback = []
            for raw in answer.get("assignments") or []:
                if not isinstance(raw, dict) or str(raw.get("ra")) not in aliases:
                    continue
                application, errors = self.validate_assignment(raw, aliases[str(raw["ra"])], catalog, known_aliases)
                previous = results.get(str(raw["ra"]))
                # 더 나은(오류가 적은) 답만 남긴다.
                if previous is None or len(errors) < len(previous[1]):
                    results[str(raw["ra"])] = (application, errors)
                if errors:
                    feedback.append(f"{raw['ra']}: " + "; ".join(errors))
            missing = [alias for alias in aliases if alias not in results]
            if missing:
                feedback.append(f"missing assignments for: {', '.join(missing)}")
            if not feedback:
                break
            messages = [
                *messages,
                {"role": "assistant", "content": content},
                {"role": "user", "content": "Your previous answer had problems:\n- " + "\n- ".join(feedback) + "\nReturn corrected JSON only, one assignment per RA."},
            ]
        report.extend(group_errors)
        for alias, info in aliases.items():
            application, errors = results.get(
                alias,
                (
                    {
                        "schemeKey": "unclassified",
                        "status": "suggested",
                        "origin": "ai",
                        "rationale": "",
                        "premiseBindings": [],
                        "conclusionNodeIds": info["conclusions"],
                        "criticalQuestionResponses": [],
                        "notes": "",
                        "customSchemeName": None,
                        "alternatives": [],
                    },
                    ["no valid assignment returned"],
                ),
            )
            application["catalogVersion"] = version
            if errors:
                application["errors"] = errors
                report.append(f"{info['ra']['nodeID']}: " + "; ".join(errors))
            info["ra"]["schemeApplication"] = application
        return report

    def assign(self) -> Message:
        graph = self.parse_json_object(self._text(self.graph_json))
        if graph.get("status") != "ok":
            self.status = f"skipped: {graph.get('status')}"
            return Message(text=json.dumps(graph, ensure_ascii=False, indent=2))
        catalog_text = self._text(self.scheme_catalog)
        catalog = self.read_catalog(catalog_text)
        if not catalog:
            raise ValueError("Scheme catalog is empty; the relay server must send the scheme catalog.")
        template = self._text(self.prompt_template)
        if not template.strip():
            raise ValueError("Scheme Prompt Template is empty.")
        version = (graph.get("meta") or {}).get("catalogVersions", {}).get("scheme")
        errors: list[str] = []
        for group in self.groups(graph):
            errors.extend(self.assign_group(group, catalog, catalog_text, template, version))
        ras = [n for n in graph["AIF"]["nodes"] if n.get("type") == "RA"]
        counts: dict[str, int] = {}
        for ra in ras:
            key = ra["schemeApplication"]["schemeKey"]
            counts[key] = counts.get(key, 0) + 1
        graph.setdefault("meta", {})["schemes"] = {"raCount": len(ras), "keys": counts, "errors": errors, "model": self._text(self.model_name)}
        self.status = f"{len(ras)} RA classified ({counts.get('unclassified', 0)} unclassified)"
        return Message(text=json.dumps(graph, ensure_ascii=False, indent=2))

from __future__ import annotations

import json
import re

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
# 정답 그래프의 쟁점 수는 1~4개(평균 2.65)다. 여유를 두어 5개까지 받고, 몇 개를 고를지는 판결문이 정한다.
MAX_SELECTED = 5
RESERVED = ("unclassified", "custom")


def text_hash(text: str) -> str:
    value = 0xCBF29CE484222325
    for byte in text.encode("utf-8"):
        value ^= byte
        value = (value * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
    return f"fnv1a64:{value:016x}"


class ResultValidator(Component):
    display_name = "AIF Result Validator"
    description = (
        "Validation stage before the final output: graph structure, at most 5 distinct catalog issues, issue IDs "
        "in the catalog, scheme keys, premise/conclusion references of every scheme application and summary hashes. "
        "Structural or catalog violations set status to invalid with the reasons; nothing is silently repaired."
    )
    icon = "ShieldCheck"
    name = "ResultValidator"

    inputs = [
        MessageTextInput(name="graph_json", display_name="Graph JSON", required=True),
        MessageTextInput(name="issue_catalog", display_name="Issue Catalog (JSON lines)", required=True),
        MessageTextInput(name="scheme_catalog", display_name="Scheme Catalog (JSON lines)", required=True),
    ]

    outputs = [Output(display_name="Final AIF JSON", name="final_graph", method="validate")]

    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def _lines(text: str, key: str) -> dict[str, dict]:
        result = {}
        for line in str(text or "").splitlines():
            try:
                item = json.loads(line, strict=False)
            except ValueError:
                continue
            if isinstance(item, dict) and item.get(key):
                result[str(item[key])] = item
        return result

    @staticmethod
    def check(graph: dict, issue_ids: set[str], schemes: dict[str, dict]) -> tuple[list[str], list[str]]:
        errors: list[str] = []
        warnings: list[str] = []
        aif = graph.get("AIF") or {}
        nodes = aif.get("nodes") or []
        edges = aif.get("edges") or []
        ids = [n.get("nodeID") for n in nodes]
        if len(ids) != len(set(ids)):
            errors.append("duplicate nodeID")
        idset = set(ids)
        incoming: dict[str, set[str]] = {}
        outgoing: dict[str, set[str]] = {}
        for edge in edges:
            if edge.get("fromID") not in idset or edge.get("toID") not in idset:
                errors.append(f"edge {edge.get('edgeID')} references a missing node")
                continue
            incoming.setdefault(edge["toID"], set()).add(edge["fromID"])
            outgoing.setdefault(edge["fromID"], set()).add(edge["toID"])

        selected = [n.get("issueRef", {}).get("issueId") for n in nodes if n.get("type") == "ISSUE"]
        if len(selected) > MAX_SELECTED:
            errors.append(f"{len(selected)} ISSUE nodes; at most {MAX_SELECTED} are allowed")
        if len(selected) != len(set(selected)):
            errors.append("the same catalog issue is selected more than once")
        for issue_id in selected:
            if issue_id not in issue_ids:
                errors.append(f"ISSUE issueId {issue_id!r} is not in the issue catalog")

        for node in nodes:
            node_id = node.get("nodeID")
            if node.get("type") in ("I", "ISSUE"):
                if node.get("summary") and node.get("summarySourceHash") != text_hash(node.get("text") or ""):
                    warnings.append(f"{node_id}: summarySourceHash does not match the text")
                if not node.get("summary"):
                    warnings.append(f"{node_id}: no summary")
            if node.get("type") != "RA":
                continue
            if not incoming.get(node_id) or not outgoing.get(node_id):
                errors.append(f"RA {node_id} needs at least one premise and one conclusion")
            application = node.get("schemeApplication")
            if not isinstance(application, dict):
                warnings.append(f"RA {node_id}: no scheme application")
                continue
            key = application.get("schemeKey")
            if key not in schemes and key not in RESERVED:
                warnings.append(f"RA {node_id}: scheme key {key!r} is not allowed")
            for binding in application.get("premiseBindings") or []:
                for ref in binding.get("nodeIds") or []:
                    if ref not in incoming.get(node_id, set()):
                        warnings.append(f"RA {node_id}: premise binding {ref} is not an incoming node")
            for ref in application.get("conclusionNodeIds") or []:
                if ref not in outgoing.get(node_id, set()):
                    warnings.append(f"RA {node_id}: conclusion {ref} is not an outgoing node")
            for error in application.get("errors") or []:
                warnings.append(f"RA {node_id}: {error}")
        return errors, warnings

    def validate(self) -> Message:
        text = self._text(self.graph_json).strip()
        match = _FENCE.match(text)
        graph = json.loads(match.group(1) if match else text, strict=False)
        meta = graph.setdefault("meta", {})
        if graph.get("status") != "ok":
            meta["validation"] = {"ok": graph.get("status") == "no_issues", "errors": graph.get("errors") or [], "warnings": []}
            self.status = f"passed through: {graph.get('status')}"
            return Message(text=json.dumps(graph, ensure_ascii=False, indent=2))
        errors, warnings = self.check(
            graph,
            set(self._lines(self._text(self.issue_catalog), "issue_id")),
            self._lines(self._text(self.scheme_catalog), "schemeKey"),
        )
        meta["validation"] = {"ok": not errors, "errors": errors, "warnings": warnings}
        if errors:
            graph["status"] = "invalid"
            graph["errors"] = errors
        self.status = f"{'invalid' if errors else 'ok'}: {len(errors)} errors / {len(warnings)} warnings"
        return Message(text=json.dumps(graph, ensure_ascii=False, indent=2))
